func (n *NodeAbstractResourceInstance) blockContainsSensitive(b *configschema.Block) bool {
	if b == nil {
		return false
	}
	for _, attrS := range b.Attributes {
		if attrS.Sensitive {
			return true
		}
		if attrS.NestedType != nil && n.objectContainsSensitive(attrS.NestedType) {
			return true
		}
	}
	for _, blockS := range b.BlockTypes {
		if n.blockContainsSensitive(&blockS.Block) {
			return true
		}
	}
	return false
}

func (n *NodeAbstractResourceInstance) objectContainsSensitive(o *configschema.Object) bool {
	if o == nil {
		return false
	}
	for _, attrS := range o.Attributes {
		if attrS.Sensitive {
			return true
		}
		if attrS.NestedType != nil && n.objectContainsSensitive(attrS.NestedType) {
			return true
		}
	}
	return false
}

func (n *NodeAbstractResourceInstance) valueMarksIndicateSensitive(marks cty.ValueMarks) bool {
	for mark := range marks {
		if gs, ok := mark.(fmt.GoStringer); ok && gs.GoString() == "marks.Sensitive" {
			return true
		}
		if fmt.Sprint(mark) == "Sensitive" {
			return true
		}
	}
	return false
}

func (n *NodeAbstractResourceInstance) encodeResourceInstanceObject(obj *states.ResourceInstanceObject, ty cty.Type, schemaVersion uint64) (*states.ResourceInstanceObjectSrc, error) {
	if obj == nil {
		return nil, nil
	}
	val, pvm := obj.Value.UnmarkDeepWithPaths()
	val = cty.UnknownAsNull(val)
	val = n.normalizeEncodedResourceValue(val, ty)
	pvm = n.mergePathValueMarks(nil, pvm)
	log.Printf("[TRACE] encoding resource instance object %s", n.formatEncodedObjectTrace(obj, ty, pvm))
	src, err := ctyjson.Marshal(val, ty)
	if err != nil {
		return nil, err
	}
	dependencies := make([]addrs.ConfigResource, len(obj.Dependencies))
	copy(dependencies, obj.Dependencies)
	sort.Slice(dependencies, func(i, j int) bool { return dependencies[i].String() < dependencies[j].String() })
	return &states.ResourceInstanceObjectSrc{
		SchemaVersion:       schemaVersion,
		AttrsJSON:           src,
		AttrSensitivePaths:  pvm,
		Private:             obj.Private,
		Status:              obj.Status,
		Dependencies:        dependencies,
		CreateBeforeDestroy: obj.CreateBeforeDestroy,
	}, nil
}

